import ast, os, sys, re

ROOT = "/app/tally/reports"
LAYER = {"errors": 0, "tables": 0, "state": 0, "system": 0, "formatting": 1, "model": 1, "loading": 2, "aggregate": 3, "renderers": 4, "cli": 5}

mods = {}
for dp, dn, fn in os.walk(ROOT):
    dn[:] = [d for d in dn if d != "__pycache__"]
    for f in fn:
        if f.endswith(".py"):
            p = os.path.join(dp, f)
            rel = os.path.relpath(p, ROOT)[:-3].replace(os.sep, ".")
            name = "tally.reports" + ("" if rel == "__init__" else "." + (rel[:-9] if rel.endswith(".__init__") else rel))
            mods[name] = p
problems = []
for name, p in mods.items():
    n = sum(1 for _ in open(p, encoding="utf-8"))
    if n > 400:
        problems.append(f"{name}: {n} lines")

def layer_of(name):
    if name == "tally.reports":
        return 6
    return LAYER[name.split(".")[2]]

graph = {m: set() for m in mods}
for name, p in mods.items():
    tree = ast.parse(open(p, encoding="utf-8").read())
    is_pkg = p.endswith("__init__.py")
    pkg = name if is_pkg else name.rsplit(".", 1)[0]
    for node in ast.walk(tree):
        targets = []
        if isinstance(node, ast.Import):
            for a in node.names:
                targets.append(a.name)
        elif isinstance(node, ast.ImportFrom):
            if node.level:
                base = pkg.split(".")
                base = base[: len(base) - (node.level - 1)]
                modname = ".".join(base + ([node.module] if node.module else []))
            else:
                modname = node.module
            for a in node.names:
                cand = modname + "." + a.name
                targets.append(cand if cand in mods else modname)
        for t in targets:
            if t.startswith("tally"):
                if t not in mods:
                    problems.append(f"{name}: imports unknown {t}")
                    continue
                graph[name].add(t)
                if name != "tally.reports" and layer_of(t) > layer_of(name):
                    problems.append(f"{name} (L{layer_of(name)}) imports {t} (L{layer_of(t)})")
            elif t.split(".")[0] in ("importlib",):
                problems.append(f"{name}: importlib")
        for n2 in ast.walk(tree):
            if isinstance(n2, ast.Name) and n2.id == "__import__":
                problems.append(f"{name}: __import__")
# cycles
WHITE, GREY, BLACK = 0, 1, 2
color = {m: WHITE for m in mods}
def dfs(m, stack):
    color[m] = GREY
    for t in graph[m]:
        if t == m:
            problems.append(f"self import {m}")
            continue
        if color[t] == GREY:
            problems.append("cycle: " + " -> ".join(stack + [m, t]))
        elif color[t] == WHITE:
            dfs(t, stack + [m])
    color[m] = BLACK
for m in mods:
    if color[m] == WHITE:
        dfs(m, [])

# unused imports / undefined names (crude)
import builtins
for name, p in mods.items():
    tree = ast.parse(open(p, encoding="utf-8").read())
    imported = {}
    for node in tree.body:
        if isinstance(node, ast.Import):
            for a in node.names:
                imported[(a.asname or a.name).split(".")[0]] = node
        elif isinstance(node, ast.ImportFrom) and node.module != "__future__":
            for a in node.names:
                imported[a.asname or a.name] = node
    used = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)}
    if not p.endswith("__init__.py"):
        for k in imported:
            if k not in used:
                problems.append(f"{name}: unused import {k}")
    # from-import of private variables from state/system
    for node in tree.body:
        if isinstance(node, ast.ImportFrom):
            m = node.module or ""
            if m.endswith("state") or m.endswith("system"):
                for a in node.names:
                    if a.name.startswith("_"):
                        problems.append(f"{name}: from {m} import {a.name}")
# assignments at top-level of state vars elsewhere
for name, p in mods.items():
    tree = ast.parse(open(p, encoding="utf-8").read())
    for node in tree.body:
        if isinstance(node, (ast.Assign, ast.AnnAssign)):
            tg = node.targets if isinstance(node, ast.Assign) else [node.target]
            for t in tg:
                if getattr(t, "id", "") in ("_LOCALE", "_CURRENCY", "_FMT_CACHE", "_WIDTH_CACHE", "_WARNINGS") and name != "tally.reports.state":
                    problems.append(f"{name}: assigns {t.id}")
    if name == "tally.reports":
        for node in tree.body:
            if not isinstance(node, (ast.Import, ast.ImportFrom)) and not (isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant)) and not (isinstance(node, ast.Assign) and node.targets[0].id == "__all__"):
                problems.append("__init__ has other statement")
    if name.endswith(".__init__"):
        pass
print("\n".join(problems) or "static OK", len(mods), "modules")

